create table tutores (
    id integer primary key generated by default as identity,
    nome varchar(150) not null,
    telefone varchar(30),
    email varchar(150),
    criado_em date default now()
);

create table veterinarios (
    id integer primary key generated by default as identity,
    nome varchar(150) not null,
    crmv varchar(50) unique,
    especialidade varchar(100),
    ativo bool default True,
    criado_em date default now()
);

create table pets (
    id integer primary key generated by default as identity,
    nome varchar(150) not null,
    especie varchar(50) not null,
    data_nascimento date,
    tutor_id integer,
    criado_em date default now()
);

alter table pets add constraint fk_pets_tutor foreign key (tutor_id) REFERENCES tutores (id);

create table consultas (
    id integer primary key generated by default as identity,
    pet_id integer not null,
    veterinario_id integer not null,
    data_consulta date not null,
    motivo varchar(255),
    valor_consulta numeric(10,2),
    retorno_agendado_em date,
    criado_em date default now()
);

alter table consultas add constraint fk_consultas_pet foreign key (pet_id) REFERENCES pets (id);
alter table consultas add constraint fk_consultas_veterinario foreign key (veterinario_id) REFERENCES veterinarios (id);

