select count(*) as registros from tutores;
select count(*) as registros from veterinarios;
select count(*) as registros from pets;
select count(*) as registros from consultas;

select id, nome, especialidade, ativo from veterinarios order by nome;

select c.id as id_consulta, p.nome as nome_pet, t.nome as nome_tutor, v.nome as nome_veterinario, c.data_consulta, c.motivo from consultas c
    inner join pets p on c.pet_id = p.id
    inner join veterinarios v on c.veterinario_id = v.id
    inner join tutores t on p.tutor_id = t.id order by c.data_consulta desc;

select id, nome, data_nascimento, tutor_id from pets where especie like 'gato' order by data_nascimento;

select c.id, p.nome as nome_pet, v.nome as nome_veterinario, c.data_consulta, c.retorno_agendado_em from consultas c
                                                                                                             inner join pets p on c.pet_id = p.id
                                                                                                             inner join veterinarios v on c.veterinario_id = v.id where c.retorno_agendado_em is not null order by c.retorno_agendado_em desc;

select v.nome as nome_veterinario, count(c.id) as total_consultas from veterinarios v
    left join consultas c on v.id = c.veterinario_id group by v.id having count(c.id) >= 1 order by total_consultas desc;

select t.nome as nome_tutor, count(distinct p.id) as qtde_pets, coalesce(count(c.id),0) as qtde_consultas from tutores t
    inner join pets p on t.id = p.tutor_id
    left join consultas c on p.id = c.pet_id group by t.id order by nome_tutor;

with numeracao_consultas as (
select p.nome as nome_pet,c.data_consulta, row_number() over (partition by p.id order by c.data_consulta desc) as ordem, v.nome as nome_veterinario, c.motivo as motivo from pets p
    inner join consultas c on p.id = c.pet_id
    inner join veterinarios v on c.veterinario_id = v.id)
select nome_pet, data_consulta as data_ultima_consulta, nome_veterinario, motivo from numeracao_consultas where ordem = 1 order by nome_pet;

select p.nome as nome_pet, count(c.id) as qtde_consultas from pets p
    left join consultas c on p.id = c.pet_id group by p.id having count(c.id) > 1 order by qtde_consultas desc;

select v.nome as nome_veterinario, sum(c.valor_consulta) as total_faturado, count(c.id) as qtde_consultas from veterinarios v
    inner join consultas c on v.id = c.veterinario_id group by v.id order by total_faturado desc;

select to_char(date_trunc('month', data_consulta),'YYYY-MM') as ano_mes, count(id) as total_consultas, sum(valor_consulta) as faturamento_mes
from consultas group by date_trunc('month', data_consulta) order by ano_mes;

with ordenamento_fat_mes_vet as (
select date_trunc('month', c.data_consulta) as data, row_number() over (partition by date_trunc('month', c.data_consulta) order by sum(c.valor_consulta) desc) as ordem, v.nome as nome_veterinario, sum(c.valor_consulta) as faturamento_mes_vet from veterinarios v
    inner join consultas c on v.id = c.veterinario_id group by data, nome_veterinario)
select to_char(data,'YYYY-MM') as ano_mes, nome_veterinario, faturamento_mes_vet from ordenamento_fat_mes_vet where ordem = 1 order by ano_mes;

with tutor_consulta_info as (
select t.nome as nome_tutor, count(c.id) as qtde_consultas, sum(c.valor_consulta) as total_gasto from tutores t
    inner join pets p on t.id = p.tutor_id
    left join consultas c on p.id = c.pet_id group by t.id)
select nome_tutor, qtde_consultas, total_gasto, round(100 * total_gasto/sum(total_gasto) over (),2) as percentual_clinica from tutor_consulta_info order by total_gasto desc;